"use client";

import { NativeButton } from "../native-button-shadcnui";

export function NativeButtonDefault() {
  return <NativeButton>Click</NativeButton>;
}

export function NativeButtonGlow() {
  return <NativeButton glow>Glow Effect</NativeButton>;
}

export function NativeButtonOutline() {
  return <NativeButton variant="outline">Learn More</NativeButton>;
}

export function NativeButtonLoading() {
  return <NativeButton loading>Processing...</NativeButton>;
}

export function NativeButtonDisabled() {
  return <NativeButton disabled>Disabled</NativeButton>;
}

import { Button, ButtonProps } from "@/packages/components/react-shadcn/src/ui/button";
import { cn } from "@/packages/components/react-shadcn/src/lib/utils";
import { Loader2 } from "lucide-react";
import { ReactNode } from "react";

export interface NativeButtonProps extends ButtonProps {
  children: ReactNode;
  loading?: boolean;
  glow?: boolean;
}

const NativeButton = ({
  className,
  variant = "default",
  size = "lg",
  children,
  loading = false,
  glow = false,
  disabled,
  ...props
}: NativeButtonProps) => {
  const buttonContent = (
    <>
      {loading && (
        <Loader2 aria-hidden="true" className="w-4 h-4 mr-2 animate-spin" />
      )}
      <span
        className={cn(
          "flex items-center gap-2",
          loading && "motion-safe:animate-[pulse_1s_ease-in-out_infinite]"
        )}
      >
        {children}
      </span>
    </>
  );

  const glassmorphismClassName = cn(
    "cursor-pointer h-12 rounded-md px-7 text-sm relative overflow-hidden",
    "transition-[scale,box-shadow,background-color,border-color,color] duration-200",
    !disabled &&
